 const auto layoutSheet=twice.workbook.at("sheets")[0].at("id").get<std::string>();const Json newMerge=Json::array({{{"row1",1},{"col1",1},{"row2",1},{"col2",2}}});auto tableSource=twice;tableSource.entries["xl/worksheets/sheet1.xml"]="<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData/><tableParts count=\"1\"><tablePart/></tableParts></worksheet>";bool mergeBlocked=false;try{preflightWorksheetLayout(tableSource,layoutSheet,newMerge);}catch(const std::exception&){mergeBlocked=true;}require(mergeBlocked,"merge preview rejects opaque imported table ownership");preflightWorksheetLayout(tableSource,layoutSheet,Json::array());
